"""
    Breath first search on a given graph
    >>> bfs({'A': set(['B']),
    ... 'B': set(['C']),
    ... 'C': set()}, 'A', 'C')
    ['A', 'B', 'C']
    """
def bfs(graph: Any, start: Any, goal: Any) -> object {
    queue = [(start, [start])];
    while queue {
        (vertex, path) = queue.pop(0);
        for next_node in (graph[vertex] - `set(path)) {
            if (next_node == goal) {
                return (path + [next_node]);
            } else {
                queue.append((next_node, (path + [next_node])));
            }
        }
    }
    return [];
}

"""Serializes sudoku grids into a string.

    Args:
        grid (list, None): This list characterizes a sudoku grid. The ints are
        in 0-9, where 0 denotes an empty cell and any other number is a filled
        cell.

    Returns:
        str: This string represents a walk through the grid from top to bottom
            and left to right.
    """
def serialize(grid: Any) -> object {
    string = '';
    if grid {
        for row in grid {
            for cell in row {
                string += str(cell);
            }
        }
    }
    return string;
}

